+  return 0;
+}
+
+static int flash_test_read_exact(int fd, uint32_t offset,
+                                 FAR uint8_t *buffer, uint32_t length)
+{
+  ssize_t received;
+
+  if (lseek(fd, offset, SEEK_SET) < 0)
+    {
+      return -errno;
+    }
+
+  received = read(fd, buffer, length);
+  if (received < 0)
+    {
+      return -errno;
+    }
+
+  return received == length ? OK : -EIO;
+}
+
+static int flash_test_validate_range(uint32_t offset, uint32_t length,
+                                     uint32_t maximum_length)
+{
+  struct d13x_spinor_info_s info;
+  int ret;
+
+  if (length == 0 || length > maximum_length)
+    {
+      return -EINVAL;
+    }
+
+  ret = flash_test_get_info(&info);
+  if (ret < 0)
+    {
+      return ret;
+    }
+
+  if (offset >= info.capacity || length > info.capacity - offset)
+    {
