+
+static uint32_t flash_test_crc32_update(uint32_t crc,
+                                        FAR const uint8_t *buffer,
+                                        uint32_t length)
+{
+  uint32_t byte;
+  unsigned int bit;
+
+  while (length-- > 0)
+    {
+      crc ^= *buffer++;
+      for (bit = 0; bit < 8; bit++)
+        {
+          byte = (uint32_t)-(int32_t)(crc & 1u);
+          crc = (crc >> 1) ^ (0xedb88320u & byte);
+        }
+    }
