  if (priv->alloc_index == priv->buffer_num) {
    auderr("audio alloc buffer failed: all buffers allocated\n");
    return -ENOMEM;
  }

  if (priv->alloc_addr == NULL) {
    priv->alloc_addr = kumm_memalign(32, priv->buffer_num * priv->buffer_size);
