    hal_audio_enable_rx_global(codec);
    /* Enable DMIC ADOUT SHIFT */
    hal_audio_enable_dmic_adout_shift(codec);
    /* Enable DMIC DRQ */
    hal_audio_dmic_enable_drq(codec);
}

