  }

  HAL_LOCK(hdma);
  switch (id) {
  case DMA_CB_INIT:
    hdma->init_cb = NULL;
    break;
  case DMA_CB_DEINIT:
    hdma->deinit_cb = NULL;
    break;
  case DMA_CB_XFER_HALF_TASK_COMPLETE_CB:
