    hdma->xfer_full_task_complete_cb = NULL;
    break;
  case DMA_CB_XFER_ALL_TASKS_COMPLETE_CB:
    hdma->xfer_all_tasks_complete_cb = NULL;
    break;
  case DMA_CB_XFER_ERROR_CB:
    hdma->xfer_error_cb = NULL;
    break;
  case DMA_CB_XFER_ABORT_CB:
