/****************************************************************************
 * vendor/artinchip/chips/artinchips/drv/audio/aic_drv_dmic.c
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>

#include <nuttx/arch.h>
#include <nuttx/audio/audio.h>
#include <nuttx/irq.h>
#include <nuttx/kmalloc.h>
#include <nuttx/queue.h>

#include <aic_drv_dma.h>
#include <aic_soc.h>
#include <drv_dma.h>
#include <hal_audio.h>
#include <hal_dma.h>

#define AIC_DMIC_DMA_CHANNEL 1
#define AIC_DMIC_FIFO_BYTES  8192
#define AIC_DMIC_BUFFER_COUNT 2

struct aic_dmic_s {
  struct audio_lowerhalf_s dev;
  hal_audio_handle_t audio;
  struct aic_dma_chan_s dma;
  struct dq_queue_s pendq;
  FAR struct ap_buffer_s *active;
  FAR uint8_t *alloc_addr;
  uint32_t samplerate;
  uint8_t channels;
  uint8_t samplebits;
  uint8_t alloc_index;
  bool started;
  bool reserved;
  bool xrun;
};

static struct aic_dmic_s g_aic_dmic;

static int aic_dmic_start_next(struct aic_dmic_s *priv);

static void aic_dmic_complete(FAR struct aic_dmic_s *priv,
                              FAR struct ap_buffer_s *apb, int status) {
  if (apb == NULL) {
    return;
  }

  apb_free(apb);
  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_DEQUEUE, apb, status);
}

static void aic_dmic_dma_error(hal_dma_handle_t *hdma) {
  FAR struct aic_dmic_s *priv = hdma->parent;
  FAR struct ap_buffer_s *apb;
  irqstate_t flags;

  flags = enter_critical_section();
  priv->started = false;
  apb = priv->active;
  priv->active = NULL;
  leave_critical_section(flags);

  hal_audio_dmic_stop(&priv->audio);
  aic_dmic_complete(priv, apb, -EIO);
  while ((apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq)) != NULL) {
    aic_dmic_complete(priv, apb, -EIO);
  }

  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_IOERR, NULL, -EIO);
  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, -EIO);
}

static void aic_dmic_dma_complete(hal_dma_handle_t *hdma) {
  FAR struct aic_dmic_s *priv = hdma->parent;
  FAR struct ap_buffer_s *apb;
  irqstate_t flags;

  flags = enter_critical_section();
  apb = priv->active;
  priv->active = NULL;
  leave_critical_section(flags);

  if (apb != NULL) {
    up_invalidate_dcache((uintptr_t)apb->samp,
                         (uintptr_t)apb->samp + apb->nmaxbytes);
    apb->curbyte = 0;
    apb->nbytes = apb->nmaxbytes;
    aic_dmic_complete(priv, apb, OK);
  }

  if (priv->started && aic_dmic_start_next(priv) < 0) {
    priv->xrun = true;
  }
}

static int aic_dmic_start_next(struct aic_dmic_s *priv) {
  FAR struct ap_buffer_s *apb;
  irqstate_t flags;
  hal_status_e status;

  flags = enter_critical_section();
  if (priv->active != NULL) {
    leave_critical_section(flags);
    return OK;
  }

  apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq);
  priv->active = apb;
  leave_critical_section(flags);

  if (apb == NULL) {
    return -EAGAIN;
  }

  up_invalidate_dcache((uintptr_t)apb->samp,
                       (uintptr_t)apb->samp + apb->nmaxbytes);
  status = hal_dma_start_it(&priv->dma.hal,
                            DMIC_RXFIFO_DATA_REG(&priv->audio),
                            (uint32_t)apb->samp, apb->nmaxbytes);
  if (status != HAL_OK) {
    flags = enter_critical_section();
    priv->active = NULL;
    dq_addfirst(&apb->dq_entry, &priv->pendq);
    leave_critical_section(flags);
    return -EIO;
  }

  return OK;
}

static int aic_dmic_getcaps(FAR struct audio_lowerhalf_s *dev, int type,
                            FAR struct audio_caps_s *caps) {
  FAR struct aic_dmic_s *priv = (FAR struct aic_dmic_s *)dev;

  caps->ac_format.hw = 0;
  caps->ac_controls.w = 0;
  if (caps->ac_type == AUDIO_TYPE_QUERY &&
      caps->ac_subtype == AUDIO_TYPE_QUERY) {
    caps->ac_channels = 0x12;
    caps->ac_controls.b[0] = AUDIO_TYPE_INPUT;
    caps->ac_format.hw = 1 << (AUDIO_FMT_PCM - 1);
  } else if (caps->ac_type == AUDIO_TYPE_INPUT &&
             caps->ac_subtype == AUDIO_TYPE_QUERY) {
    caps->ac_channels = 0x12;
    caps->ac_controls.hw[0] = AUDIO_SAMP_RATE_8K | AUDIO_SAMP_RATE_16K |
                              AUDIO_SAMP_RATE_32K | AUDIO_SAMP_RATE_48K;
    caps->ac_controls.b[2] = priv->samplebits;
  }

  return caps->ac_len;
}

static int aic_dmic_configure(FAR struct audio_lowerhalf_s *dev,
                              FAR const struct audio_caps_s *caps) {
  FAR struct aic_dmic_s *priv = (FAR struct aic_dmic_s *)dev;
  uint32_t samplerate;
  uint8_t channels;
  uint8_t samplebits;

  if (caps->ac_type != AUDIO_TYPE_INPUT) {
    return -ENOTTY;
  }

  samplerate = caps->ac_controls.hw[0] |
               ((uint32_t)caps->ac_controls.b[3] << 16);
  channels = caps->ac_channels & 0x0f;
  samplebits = caps->ac_controls.b[2];
  if ((channels != 1 && channels != 2) || samplebits != 16 ||
      (samplerate != 8000 && samplerate != 12000 &&
       samplerate != 16000 && samplerate != 24000 &&
       samplerate != 32000 && samplerate != 48000)) {
    return -EINVAL;
  }

  priv->samplerate = samplerate;
  priv->channels = channels;
  priv->samplebits = samplebits;
  return OK;
}

static int aic_dmic_shutdown(FAR struct audio_lowerhalf_s *dev);

static int aic_dmic_start(FAR struct audio_lowerhalf_s *dev) {
  FAR struct aic_dmic_s *priv = (FAR struct aic_dmic_s *)dev;
  hal_dma_handle_t *hdma = &priv->dma.hal;
  int ret;

  if (priv->started) {
    return OK;
  }

  hal_audio_handle_init(&priv->audio);
  if (hal_audio_init(&priv->audio) != HAL_OK ||
      hal_audio_dmic_configure(&priv->audio, priv->samplerate,
                               priv->channels) != HAL_OK) {
    return -EIO;
  }

  hdma->init.src_data_width = priv->channels == 1 ? DMA_DATA_WIDTH_2_BYTES :
                                                    DMA_DATA_WIDTH_4_BYTES;
  hdma->init.snk_data_width = hdma->init.src_data_width;
  if (hal_dma_init(hdma) != HAL_OK) {
    return -EIO;
  }

  priv->started = true;
  priv->xrun = false;
  ret = aic_dmic_start_next(priv);
  if (ret < 0) {
    priv->started = false;
    hal_dma_deinit(hdma);
    return ret;
  }

  if (hal_audio_dmic_start(&priv->audio) != HAL_OK) {
    aic_dmic_shutdown(dev);
    return -EIO;
  }

  return OK;
}

#ifndef CONFIG_AUDIO_EXCLUDE_STOP
static int aic_dmic_stop(FAR struct audio_lowerhalf_s *dev) {
  FAR struct aic_dmic_s *priv = (FAR struct aic_dmic_s *)dev;
  FAR struct ap_buffer_s *apb;
  irqstate_t flags;

  priv->started = false;
  hal_audio_dmic_stop(&priv->audio);
  hal_dma_abort(&priv->dma.hal);
  hal_dma_deinit(&priv->dma.hal);
  hal_audio_deinit(&priv->audio);

  flags = enter_critical_section();
  apb = priv->active;
  priv->active = NULL;
  leave_critical_section(flags);
  aic_dmic_complete(priv, apb, OK);

  while ((apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq)) != NULL) {
    aic_dmic_complete(priv, apb, OK);
  }

  priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK);
  return OK;
}
#endif

static int aic_dmic_shutdown(FAR struct audio_lowerhalf_s *dev) {
#ifndef CONFIG_AUDIO_EXCLUDE_STOP
  return aic_dmic_stop(dev);
#else
  return OK;
#endif
}

static int aic_dmic_allocbuffer(FAR struct audio_lowerhalf_s *dev,
                                FAR struct audio_buf_desc_s *bufdesc) {
  FAR struct aic_dmic_s *priv = (FAR struct aic_dmic_s *)dev;
  FAR struct ap_buffer_s *apb;

  if (bufdesc->numbytes != AIC_DMIC_FIFO_BYTES ||
      priv->alloc_index >= AIC_DMIC_BUFFER_COUNT) {
    return -EINVAL;
  }

  if (priv->alloc_addr == NULL) {
    priv->alloc_addr = kumm_memalign(32, AIC_DMIC_FIFO_BYTES *
                                     AIC_DMIC_BUFFER_COUNT);
    if (priv->alloc_addr == NULL) {
      return -ENOMEM;
    }
  }

  apb = kumm_zalloc(sizeof(*apb));
  if (apb == NULL) {
    return -ENOMEM;
  }

  apb->i.channels = priv->channels;
  apb->crefs = 1;
  apb->nmaxbytes = AIC_DMIC_FIFO_BYTES;
  apb->samp = priv->alloc_addr + priv->alloc_index * AIC_DMIC_FIFO_BYTES;
  nxmutex_init(&apb->lock);
  priv->alloc_index++;
  *bufdesc->u.pbuffer = apb;
  return sizeof(*bufdesc);
}

static int aic_dmic_freebuffer(FAR struct audio_lowerhalf_s *dev,
                               FAR struct audio_buf_desc_s *bufdesc) {
  FAR struct aic_dmic_s *priv = (FAR struct aic_dmic_s *)dev;
  FAR struct ap_buffer_s *apb = bufdesc->u.buffer;

  if (apb == NULL) {
    return -EINVAL;
  }

  nxmutex_destroy(&apb->lock);
  kumm_free(apb);
  if (priv->alloc_index > 0) {
    priv->alloc_index--;
  }

  if (priv->alloc_index == 0) {
    kumm_free(priv->alloc_addr);
    priv->alloc_addr = NULL;
  }

  return sizeof(*bufdesc);
}

static int aic_dmic_enqueuebuffer(FAR struct audio_lowerhalf_s *dev,
                                  FAR struct ap_buffer_s *apb) {
  FAR struct aic_dmic_s *priv = (FAR struct aic_dmic_s *)dev;
  irqstate_t flags;
  bool restart;

  apb_reference(apb);
  apb->curbyte = 0;
  apb->nbytes = apb->nmaxbytes;

  flags = enter_critical_section();
  dq_addlast(&apb->dq_entry, &priv->pendq);
  restart = priv->started && priv->xrun && priv->active == NULL;
  if (restart) {
    priv->xrun = false;
  }
  leave_critical_section(flags);

  return restart ? aic_dmic_start_next(priv) : OK;
}

static int aic_dmic_ioctl(FAR struct audio_lowerhalf_s *dev, int cmd,
                          unsigned long arg) {
  FAR struct ap_buffer_info_s *info;

  if (cmd == AUDIOIOC_GETBUFFERINFO) {
    info = (FAR struct ap_buffer_info_s *)arg;
    info->buffer_size = AIC_DMIC_FIFO_BYTES;
    info->nbuffers = AIC_DMIC_BUFFER_COUNT;
    return OK;
  }

  return -ENOTTY;
}

static int aic_dmic_reserve(FAR struct audio_lowerhalf_s *dev) {
  FAR struct aic_dmic_s *priv = (FAR struct aic_dmic_s *)dev;
  irqstate_t flags;

  flags = enter_critical_section();
  if (priv->reserved) {
    leave_critical_section(flags);
    return -EBUSY;
  }

  priv->reserved = true;
  leave_critical_section(flags);
  return OK;
}

static int aic_dmic_release(FAR struct audio_lowerhalf_s *dev) {
  FAR struct aic_dmic_s *priv = (FAR struct aic_dmic_s *)dev;

  priv->reserved = false;
  return OK;
}

