{
  FAR char *endptr;
  unsigned long parsed;

  errno = 0;
  parsed = strtoul(text, &endptr, 10);
  if (errno != 0 || *text == '\0' || *endptr != '\0' ||
      parsed < minimum || parsed > maximum)
    {
      return -EINVAL;
    }

  *value = (uint32_t)parsed;
  return OK;
}

