static void d13x_dmic_dma_error(FAR hal_dma_handle_t *hdma)
{
  FAR struct d13x_dmic_s *priv = hdma->parent;
  FAR struct ap_buffer_s *apb;
  irqstate_t flags;

  flags = enter_critical_section();
  priv->started = false;
  apb = priv->active;
  priv->active = NULL;
  leave_critical_section(flags);

  d13x_dmic_hw_stop();
  d13x_dmic_complete(priv, apb, -EIO);
