   121	static int d13x_dmic_hw_configure(uint32_t samplerate, uint8_t channels)
   122	{
   123	  uint32_t rate;
   124	  uint32_t value;
   125	
   126	  switch (samplerate)
   127	    {
   128	      case 48000:
   129	        rate = 0;
   130	        break;
   131	      case 32000:
   132	        rate = 1;
   133	        break;
   134	      case 24000:
   135	        rate = 2;
   136	        break;
   137	      case 16000:
   138	        rate = 3;
   139	        break;
   140	      case 12000:
   141	        rate = 4;
   142	        break;
   143	      case 8000:
   144	        rate = 5;
   145	        break;
   146	      default:
   147	        return -EINVAL;
   148	    }
   149	
   150	  value = readl(D13X_AUDIO_RX_DMIC_IF_CTL);
   151	  value &= ~(D13X_DMIC_CLK_22579KHZ | D13X_DMIC_FS_MASK |
   152	             D13X_DMIC_DEC_MASK);
   153	  value |= D13X_DMIC_FS(rate) | D13X_DMIC_IF_EN | D13X_DMIC_DEC1_EN;
   154	  if (channels == 2)
   155	    {
   156	      value |= D13X_DMIC_DEC2_EN;
   157	    }
   158	
   159	  writel(value, D13X_AUDIO_RX_DMIC_IF_CTL);
   160	
   161	  value = readl(D13X_AUDIO_RX_HPF1_2_CTL);
   162	  value &= ~D13X_DMIC_HPF_MASK;
   163	  value |= D13X_DMIC_HPF1_EN;
   164	  if (channels == 2)
   165	    {
   166	      value |= D13X_DMIC_HPF2_EN;
   167	    }
   168	
   169	  writel(value, D13X_AUDIO_RX_HPF1_2_CTL);
   170	
   171	  value = readl(D13X_AUDIO_RX_DVC1_2_CTL);
   172	  value &= ~(D13X_DMIC_DVC_GAIN_MASK | D13X_DMIC_DVC_MASK);
   173	  value |= D13X_DMIC_DVC1_GAIN(0xa0) | D13X_DMIC_DVC1_EN;
   174	  if (channels == 2)
   175	    {
   176	      value |= D13X_DMIC_DVC2_GAIN(0xa0) | D13X_DMIC_DVC2_EN;
   177	    }
   178	
   179	  writel(value, D13X_AUDIO_RX_DVC1_2_CTL);
   180	
   181	  value = readl(D13X_AUDIO_DMIC_RXFIFO_CTL);
   182	  value &= ~(D13X_DMIC_RXFIFO_RXTH_MASK | D13X_DMIC_RXFIFO_CH_MASK);
   183	  value |= D13X_DMIC_RXFIFO_RXTH(8) | D13X_DMIC_RXFIFO_CH0_EN;
   184	  if (channels == 2)
   185	    {
   186	      value |= D13X_DMIC_RXFIFO_CH1_EN;
   187	    }
   188	
   189	  writel(value, D13X_AUDIO_DMIC_RXFIFO_CTL);
   190	  return OK;
   191	}
   192	
   193	static void d13x_dmic_hw_start(void)
   194	{
   195	  uint32_t value;
   196	
   197	  value = readl(D13X_AUDIO_DMIC_RXFIFO_CTL);
   198	  writel(value | D13X_DMIC_RXFIFO_FLUSH,
   199	         D13X_AUDIO_DMIC_RXFIFO_CTL);
   200	
   201	  value = readl(D13X_AUDIO_RX_DMIC_IF_CTL);
   202	  value &= ~D13X_DMIC_ADOUT_SHIFT_MASK;
   203	  value |= D13X_DMIC_ADOUT_SHIFT_EN | D13X_DMIC_ADOUT_SHIFT(3);
   204	  writel(value, D13X_AUDIO_RX_DMIC_IF_CTL);
   205	
   206	  value = readl(D13X_AUDIO_GLOBE_CTL);
   207	  writel(value | D13X_AUDIO_RX_GLBEN, D13X_AUDIO_GLOBE_CTL);
   208	
   209	  value = readl(D13X_AUDIO_FIFO_INT_EN);
   210	  writel(value | D13X_DMIC_DRQ_EN, D13X_AUDIO_FIFO_INT_EN);
   211	}
   212	
   213	static void d13x_dmic_hw_stop(void)
   214	{
   215	  uint32_t value;
   216	
   217	  value = readl(D13X_AUDIO_FIFO_INT_EN);
   218	  writel(value & ~D13X_DMIC_DRQ_EN, D13X_AUDIO_FIFO_INT_EN);
   219	
   220	  value = readl(D13X_AUDIO_GLOBE_CTL);
   221	  writel(value & ~D13X_AUDIO_RX_GLBEN, D13X_AUDIO_GLOBE_CTL);
   222	
   223	  value = readl(D13X_AUDIO_RX_DMIC_IF_CTL);
   224	  writel(value & ~D13X_DMIC_IF_EN, D13X_AUDIO_RX_DMIC_IF_CTL);
   225	
   226	  value = readl(D13X_AUDIO_DMIC_RXFIFO_CTL);
   227	  writel(value | D13X_DMIC_RXFIFO_FLUSH,
   228	         D13X_AUDIO_DMIC_RXFIFO_CTL);
   229	}
