   243	static void d13x_dmic_prepare_buffer(FAR struct d13x_dmic_s *priv,
   244	                                     FAR struct ap_buffer_s *apb)
   245	{
   246	  FAR uint32_t *source;
   247	  FAR int16_t *sink;
   248	  uint32_t samples;
   249	  uint32_t index;
   250	
   251	  up_invalidate_dcache((uintptr_t)apb->samp,
   252	                       (uintptr_t)apb->samp + apb->nmaxbytes);
   253	  apb->curbyte = 0;
   254	  apb->nbytes = apb->nmaxbytes;
   255	
   256	  if (priv->channels == 1)
   257	    {
   258	      source = (FAR uint32_t *)apb->samp;
   259	      sink = (FAR int16_t *)apb->samp;
   260	      samples = apb->nmaxbytes / sizeof(uint32_t);
   261	      for (index = 0; index < samples; index++)
   262	        {
   263	          sink[index] = (int16_t)source[index];
   264	        }
   265	
   266	      apb->nbytes = samples * sizeof(int16_t);
   267	    }
   268	}
