   270	static void d13x_dmic_dma_error(FAR hal_dma_handle_t *hdma)
   271	{
   272	  FAR struct d13x_dmic_s *priv = hdma->parent;
   273	  FAR struct ap_buffer_s *apb;
   274	  irqstate_t flags;
   275	
   276	  flags = enter_critical_section();
   277	  priv->started = false;
   278	  apb = priv->active;
   279	  priv->active = NULL;
   280	  if (apb != NULL)
   281	    {
   282	      dq_addlast(&apb->dq_entry, &priv->doneq);
   283	    }
   284	
   285	  while ((apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq)) != NULL)
   286	    {
   287	      dq_addlast(&apb->dq_entry, &priv->doneq);
   288	    }
   289	
   290	  priv->worker_error = true;
   291	  leave_critical_section(flags);
   292	
   293	  d13x_dmic_hw_stop();
   294	  d13x_dmic_kick_worker(priv);
   295	}
