   297	static void d13x_dmic_dma_complete(FAR hal_dma_handle_t *hdma)
   298	{
   299	  FAR struct d13x_dmic_s *priv = hdma->parent;
   300	  FAR struct ap_buffer_s *apb;
   301	  irqstate_t flags;
   302	
   303	  flags = enter_critical_section();
   304	  apb = priv->active;
   305	  priv->active = NULL;
   306	  if (apb != NULL)
   307	    {
   308	      dq_addlast(&apb->dq_entry, &priv->doneq);
   309	    }
   310	
   311	  leave_critical_section(flags);
   312	
   313	  d13x_dmic_kick_worker(priv);
   314	}
   315	
   316	static int d13x_dmic_worker(int argc, FAR char *argv[])
   317	{
   318	  FAR struct d13x_dmic_s *priv = &g_d13x_dmic;
   319	  FAR struct ap_buffer_s *apb;
   320	  irqstate_t flags;
   321	  bool error = false;
   322	  bool stopping = false;
   323	
   324	  UNUSED(argc);
   325	  UNUSED(argv);
   326	
   327	  for (;;)
   328	    {
   329	      nxsem_wait_uninterruptible(&priv->worker_sem);
   330	
   331	      for (;;)
   332	        {
   333	          flags = enter_critical_section();
   334	          apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->doneq);
   335	          if (apb == NULL)
   336	            {
   337	              error = priv->worker_error;
   338	              stopping = priv->stopping;
   339	              priv->worker_error = false;
   340	              priv->worker_wakeup = false;
   341	            }
   342	
   343	          leave_critical_section(flags);
   344	
   345	          if (apb != NULL)
   346	            {
   347	              d13x_dmic_prepare_buffer(priv, apb);
   348	              d13x_dmic_complete(priv, apb, OK);
   349	              if (priv->started && d13x_dmic_start_next(priv) < 0)
   350	                {
   351	                  priv->xrun = true;
   352	                }
   353	
   354	              continue;
   355	            }
   356	
   357	          if (error)
   358	            {
   359	              priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_IOERR, NULL,
   360	                              -EIO);
   361	              priv->dev.upper(priv->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL,
   362	                              -EIO);
   363	            }
   364	
   365	          if (stopping)
   366	            {
   367	              nxsem_post(&priv->idle_sem);
   368	            }
   369	
   370	          break;
   371	        }
   372	    }
   373	
   374	  return OK;
   375	}
   376	
   377	static int d13x_dmic_start_next(FAR struct d13x_dmic_s *priv)
   378	{
   379	  FAR struct ap_buffer_s *apb;
   380	  irqstate_t flags;
   381	  hal_status_e status;
   382	
   383	  flags = enter_critical_section();
   384	  if (priv->active != NULL)
   385	    {
   386	      leave_critical_section(flags);
   387	      return OK;
   388	    }
   389	
   390	  apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq);
   391	  priv->active = apb;
   392	  leave_critical_section(flags);
   393	
   394	  if (apb == NULL)
   395	    {
   396	      return -EAGAIN;
   397	    }
   398	
   399	  up_invalidate_dcache((uintptr_t)apb->samp,
   400	                       (uintptr_t)apb->samp + apb->nmaxbytes);
   401	  status = hal_dma_start_it(&priv->dma.hal,
   402	                            D13X_AUDIO_DMIC_RXFIFO_DATA,
   403	                            (uint32_t)apb->samp, apb->nmaxbytes);
   404	  if (status != HAL_OK)
   405	    {
   406	      flags = enter_critical_section();
   407	      priv->active = NULL;
   408	      dq_addfirst(&apb->dq_entry, &priv->pendq);
   409	      leave_critical_section(flags);
   410	      return -EIO;
   411	    }
   412	
   413	  return OK;
   414	}
