   416	static int d13x_dmic_getcaps(FAR struct audio_lowerhalf_s *dev, int type,
   417	                             FAR struct audio_caps_s *caps)
   418	{
   419	  FAR struct d13x_dmic_s *priv = (FAR struct d13x_dmic_s *)dev;
