   421	  caps->ac_format.hw = 0;
   422	  caps->ac_controls.w = 0;
   423	  if (caps->ac_type == AUDIO_TYPE_QUERY &&
   424	      caps->ac_subtype == AUDIO_TYPE_QUERY)
   425	    {
   426	      caps->ac_channels = 0x12;
   427	      caps->ac_controls.b[0] = AUDIO_TYPE_INPUT;
   428	      caps->ac_format.hw = 1 << (AUDIO_FMT_PCM - 1);
   429	    }
   430	  else if (caps->ac_type == AUDIO_TYPE_INPUT &&
   431	           caps->ac_subtype == AUDIO_TYPE_QUERY)
   432	    {
   433	      caps->ac_channels = 0x12;
   434	      caps->ac_controls.hw[0] = AUDIO_SAMP_RATE_8K | AUDIO_SAMP_RATE_16K |
   435	                                AUDIO_SAMP_RATE_32K | AUDIO_SAMP_RATE_48K;
   436	      caps->ac_controls.b[2] = priv->samplebits;
