   442	static int d13x_dmic_configure(FAR struct audio_lowerhalf_s *dev,
   443	                               FAR const struct audio_caps_s *caps)
   444	{
   445	  FAR struct d13x_dmic_s *priv = (FAR struct d13x_dmic_s *)dev;
   446	  uint32_t samplerate;
   447	  uint8_t channels;
   448	  uint8_t samplebits;
   449	
   450	  if (caps->ac_type != AUDIO_TYPE_INPUT)
   451	    {
   452	      return -ENOTTY;
   453	    }
   454	
   455	  samplerate = caps->ac_controls.hw[0] |
   456	               ((uint32_t)caps->ac_controls.b[3] << 16);
   457	  channels = caps->ac_channels & 0x0f;
   458	  samplebits = caps->ac_controls.b[2];
   459	  if ((channels != 1 && channels != 2) || samplebits != 16 ||
   460	      (samplerate != 8000 && samplerate != 12000 &&
   461	       samplerate != 16000 && samplerate != 24000 &&
   462	       samplerate != 32000 && samplerate != 48000))
   463	    {
   464	      return -EINVAL;
   465	    }
   466	
   467	  priv->samplerate = samplerate;
   468	  priv->channels = channels;
   469	  priv->samplebits = samplebits;
   470	  return OK;
   471	}
