   475	static int d13x_dmic_start(FAR struct audio_lowerhalf_s *dev)
   476	{
   477	  FAR struct d13x_dmic_s *priv = (FAR struct d13x_dmic_s *)dev;
   478	  FAR hal_dma_handle_t *hdma = &priv->dma.hal;
   479	  int ret;
   480	
   481	  if (priv->started)
   482	    {
   483	      return OK;
   484	    }
   485	
   486	  hal_audio_handle_init(&priv->audio);
   487	  priv->audio.init.samplebits = AUDIO_SAMPLEBITS_16BIT;
   488	  priv->audio.init.samplerate = priv->samplerate;
   489	  priv->audio.init.channel = priv->channels;
   490	  if (hal_audio_init(&priv->audio) != HAL_OK)
   491	    {
   492	      syslog(LOG_ERR, "[D13X] DMIC AUDIO initialization failed\n");
   493	      hal_audio_deinit(&priv->audio);
   494	      return -EIO;
   495	    }
   496	
   497	  priv->audio_ready = true;
   498	  if (d13x_dmic_hw_configure(priv->samplerate, priv->channels) < 0)
   499	    {
   500	      syslog(LOG_ERR, "[D13X] DMIC hardware configuration failed\n");
   501	      hal_audio_deinit(&priv->audio);
   502	      priv->audio_ready = false;
   503	      return -EIO;
   504	    }
   505	
   506	  hdma->init.src_data_width = DMA_DATA_WIDTH_4_BYTES;
   507	  hdma->init.snk_data_width = DMA_DATA_WIDTH_4_BYTES;
   508	  if (hal_dma_init(hdma) != HAL_OK)
   509	    {
