  hdma->state = DMA_STATE_RESET;
  /* Before configure the DMA, need to enable it */
  if (hdma->init_cb) {
    hdma->init_cb(hdma);
  }

  /* Validate channel ID */
  if (hdma->init.channel_id >= DMA_MAX_CHANNEL_NUM) {
    hdma->errcode = DMA_ERROR_CHAN_NO_EXIST;
    return HAL_ERROR;
  }
  ch = hdma->init.channel_id;

