  writel(0, DMA_CH_EN_REG(hdma, ch));
  writel(0, DMA_CH_PAUSE_REG(hdma, ch));
  writel(DMA_MEM_CFG_AHB_BURST_SEL, DMA_MEM_CFG_REG(hdma));

