   563	    {
   564	      syslog(LOG_ERR, "[D13X] DMIC hardware configuration failed\n");
   565	      hal_audio_deinit(&priv->audio);
   566	      priv->audio_ready = false;
   567	      return -EIO;
   568	    }
   569	
   570	  hdma->init.src_data_width = DMA_DATA_WIDTH_4_BYTES;
   571	  hdma->init.snk_data_width = DMA_DATA_WIDTH_4_BYTES;
   572	  hdma->work_mode = DMA_WORK_MODE_CYCLIC;
   573	  hdma->cyclic_period_len = D13X_DMIC_BUFFER_BYTES;
