   577	             (unsigned int)hal_dma_get_error(hdma));
   578	      hal_audio_deinit(&priv->audio);
   579	      priv->audio_ready = false;
   580	      return -EIO;
   581	    }
   582	
   583	  priv->dma_ready = true;
   584	  flags = enter_critical_section();
   585	  apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq);
   586	  priv->active = apb;
   587	  leave_critical_section(flags);
   588	  if (apb == NULL || d13x_dmic_start_dma(priv) < 0)
   589	    {
   590	      flags = enter_critical_section();
   591	      priv->active = NULL;
   592	      if (apb != NULL)
