684	int hal_dma_chan_prep_cyclic(struct aic_dma_chan *chan,
685	                             u32 p_buf_addr, u32 buf_len, u32 period_len,
686	                             enum dma_transfer_direction dir)
687	{
688	    struct aic_dma_task *task = NULL;
689	    struct aic_dma_task *prev = NULL;
690	    u32 task_cfg;
691	    u32 periods;
692	    u32 i;
693	    int ret;
694	
695	    CHECK_PARAM(chan != NULL && buf_len != 0 && period_len != 0, -EINVAL);
696	
697	    CHECK_PARAM((p_buf_addr%AIC_DMA_ALIGN_SIZE) == 0 && (buf_len%AIC_DMA_ALIGN_SIZE) == 0, -EINVAL);
698	
699	    ret = aic_set_burst(&chan->cfg, dir, &task_cfg);
700	    if (ret) {
701	        hal_log_err("Invalid DMA configuration\n");
702	        return -EINVAL;
703	    }
704	
705	    periods = buf_len / period_len;
706	
707	    for (i = 0; i < periods; i++) {
708	        task = aic_dma_task_alloc();
709	        if (task == NULL) {
710	            aic_dma_free_desc(chan);
711	            return -ENOMEM;
712	        }
713	
714	        task->len = period_len;
715	        if (dir == DMA_MEM_TO_DEV) {
716	            chan->irq_type = DMA_IRQ_HALF_TASK;
717	            task->src = p_buf_addr + period_len * i;
718	            task->dst = chan->cfg.dst_addr;
719	            task->cfg = task_cfg;
720	            task->cfg |= (DMA_ID_DRAM << SRC_PORT_BITSHIFT) |
721	                      ((chan->cfg.slave_id & DMA_DRQ_PORT_MASK) << DST_PORT_BITSHIFT) |
722	                      (ADDR_LINEAR_MODE << SRC_ADDR_BITSHIFT) |
723	                      (ADDR_FIXED_MODE << DST_ADDR_BITSHIFT);
724	            task->delay = DELAY_DEF_VAL;
725	            task->mode = DMA_S_WAIT_D_HANDSHAKE;
726	            aicos_dcache_clean_range((void *)(unsigned long)task->src, task->len);
727	        } else {
728	            chan->irq_type = DMA_IRQ_ONE_TASK;
729	            task->src = chan->cfg.src_addr;
730	            task->dst = p_buf_addr + period_len * i;
731	            task->cfg = task_cfg;
732	            task->cfg |= (DMA_ID_DRAM << DST_PORT_BITSHIFT) |
733	                      ((chan->cfg.slave_id & DMA_DRQ_PORT_MASK) << SRC_PORT_BITSHIFT) |
734	                      (ADDR_LINEAR_MODE << DST_ADDR_BITSHIFT) |
735	                      (ADDR_FIXED_MODE << SRC_ADDR_BITSHIFT);
736	            task->delay = DELAY_DEF_VAL;
737	            task->mode = DMA_S_HANDSHAKE_D_WAIT;
738	            aicos_dcache_clean_invalid_range((void *)(unsigned long)task->dst, task->len);
739	        }
740	
741	        prev = aic_dma_task_add(prev, task, chan);
742	    }
743	
744	    prev->p_next = __pa((unsigned long)chan->desc);
745	
746	    chan->cyclic = true;
747	
748	#ifdef AIC_DMA_DRV_DEBUG
749	    hal_dma_task_dump(chan);
750	#endif
751	    return 0;
752	}
