    25	#define MIC_TEST_CHANNELS       1
    26	#define MIC_TEST_SAMPLE_BITS    16
    27	#define MIC_TEST_WAV_HEADER_SIZE 44
    28	#define MIC_TEST_COPY_SIZE       4096
    29	
    30	static void mic_test_put_le16(FAR uint8_t *buffer, uint16_t value)
    31	{
    32	  buffer[0] = value & 0xff;
    33	  buffer[1] = value >> 8;
    34	}
    35	
    36	static void mic_test_put_le32(FAR uint8_t *buffer, uint32_t value)
    37	{
    38	  buffer[0] = value & 0xff;
    39	  buffer[1] = (value >> 8) & 0xff;
    40	  buffer[2] = (value >> 16) & 0xff;
    41	  buffer[3] = value >> 24;
    42	}
    43	
    44	static int mic_test_write_exact(int fd, FAR const uint8_t *buffer,
    45	                                size_t length)
    46	{
    47	  size_t done = 0;
    48	
    49	  while (done < length)
    50	    {
    51	      ssize_t count = write(fd, buffer + done, length - done);
    52	
    53	      if (count <= 0)
    54	        {
    55	          return -EIO;
    56	        }
    57	
    58	      done += count;
    59	    }
    60	
    61	  return OK;
    62	}
    63	
    64	static void mic_test_make_wav_header(FAR uint8_t *header,
    65	                                     uint32_t data_bytes)
    66	{
    67	  uint32_t byte_rate = MIC_TEST_SAMPLE_RATE * MIC_TEST_CHANNELS *
    68	                       (MIC_TEST_SAMPLE_BITS / 8);
    69	  uint16_t block_align = MIC_TEST_CHANNELS * (MIC_TEST_SAMPLE_BITS / 8);
    70	
    71	  memset(header, 0, MIC_TEST_WAV_HEADER_SIZE);
    72	  memcpy(&header[0], "RIFF", 4);
    73	  mic_test_put_le32(&header[4], 36 + data_bytes);
    74	  memcpy(&header[8], "WAVEfmt ", 8);
    75	  mic_test_put_le32(&header[16], 16);
    76	  mic_test_put_le16(&header[20], 1);
    77	  mic_test_put_le16(&header[22], MIC_TEST_CHANNELS);
    78	  mic_test_put_le32(&header[24], MIC_TEST_SAMPLE_RATE);
    79	  mic_test_put_le32(&header[28], byte_rate);
    80	  mic_test_put_le16(&header[32], block_align);
    81	  mic_test_put_le16(&header[34], MIC_TEST_SAMPLE_BITS);
    82	  memcpy(&header[36], "data", 4);
    83	  mic_test_put_le32(&header[40], data_bytes);
    84	}
