   103	  raw_fd = open(raw_path, O_RDONLY);
   104	  if (raw_fd < 0)
   105	    {
   106	      return -errno;
   107	    }
   108	
   109	  wav_fd = open(wav_path, O_WRONLY | O_CREAT | O_TRUNC, 0666);
   110	  if (wav_fd < 0)
   111	    {
   112	      ret = -errno;
   113	      goto out_raw;
   114	    }
   115	
   116	  buffer = malloc(MIC_TEST_COPY_SIZE);
   117	  if (buffer == NULL)
   118	    {
