   120	      goto out_wav;
   121	    }
   122	
   123	  mic_test_make_wav_header(header, file_stat.st_size);
   124	  if (mic_test_write_exact(wav_fd, header, sizeof(header)) < 0)
   125	    {
   126	      goto out_buffer;
   127	    }
   128	
   129	  while ((count = read(raw_fd, buffer, MIC_TEST_COPY_SIZE)) > 0)
