   131	      if (mic_test_write_exact(wav_fd, buffer, count) < 0)
   132	        {
   133	          goto out_buffer;
   134	        }
   135	    }
   136	
   137	  if (count < 0 || fsync(wav_fd) < 0)
   138	    {
   139	      goto out_buffer;
   140	    }
   141	
   142	  ret = OK;
   143	
   144	out_buffer:
   145	  free(buffer);
   146	out_wav:
   147	  close(wav_fd);
   148	  if (ret < 0)
   149	    {
   150	      unlink(wav_path);
   151	    }
   152	
   153	out_raw:
   154	  close(raw_fd);
   155	  return ret;
   156	}
