   158	static int mic_test_prepare_wav(FAR const char *path)
   159	{
   160	  char temp_path[CONFIG_PATH_MAX];
   161	  uint8_t signature[12];
   162	  struct stat file_stat;
   163	  ssize_t count;
   164	  int fd;
   165	  int ret;
   166	
   167	  if (stat(path, &file_stat) < 0)
   168	    {
   169	      return -errno;
   170	    }
   171	
   172	  if (file_stat.st_size <= 0)
   173	    {
   174	      return -ENODATA;
   175	    }
   176	
   177	  fd = open(path, O_RDONLY);
   178	  if (fd < 0)
   179	    {
   180	      return -errno;
   181	    }
