 96	static void d13x_fb_clean_cache(void)
 97	{
 98	  uint32_t mhcr;
 99	
100	  /* The E907 may inherit an enabled write-back cache from tinySPL. The
101	   * current custom arch has no D-cache hooks, so use T-Head's dcache.call.
102	   */
103	
104	  __asm__ __volatile__ ("csrr %0, 0x7c1" : "=r"(mhcr));
105	  if ((mhcr & THEAD_MHCR_DCACHE_ENABLE) != 0)
106	    {
107	      __asm__ __volatile__ ("fence rw, rw" ::: "memory");
108	      __asm__ __volatile__ (".long 0x0010000b" ::: "memory");
109	      __asm__ __volatile__ ("fence rw, rw" ::: "memory");
110	    }
111	}
